function clone(o){return JSON.parse(JSON.stringify(o))}function loadState(){try{let x=JSON.parse(localStorage.getItem(LS));return Object.assign(clone(baseState),x||{})}catch(e){return clone(baseState)}}function saveState(){localStorage.setItem(LS,JSON.stringify(state))}function $(id){return document.getElementById(id)}function fmtMoney(n){return Number(n).toLocaleString('ru-RU')+' ₽'}function dayDate(offset=0){const d=new Date();d.setDate(d.getDate()+Number(offset||0));return String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0')}function dateLabel(offset){if(Number(offset)===0)return 'Сегодня · '+dayDate(0);if(Number(offset)===1)return 'Завтра · '+dayDate(1);return dayDate(offset)}function plural(n,a,b,c){n=Math.abs(n)%100;let n1=n%10;if(n>10&&n<20)return c;if(n1>1&&n1<5)return b;if(n1===1)return a;return c}
