function go(id,push=true){if(push&&currentScreen&&currentScreen!==id)navStack.push(currentScreen);document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));let el=$(id);if(!el){toast('Экран пока не готов');return}el.classList.add('active');currentScreen=id;setContext();buildNav();window.scrollTo({top:0,behavior:'smooth'});onScreen(id)}function back(){let id=navStack.pop();if(!id)id=state.role==='worker'?'workerHome':state.role==='contractor'?'contractorHome':'landing';go(id,false)}
function onScreen(id){if(id==='workerHome')renderWorkerHome();if(id==='workerSearch')syncFilters();if(id==='map')changeRadius(state.filters.radius||8);if(id==='deck')renderDeck();if(id==='workerShifts')renderWorkerShifts();if(id==='workerFavorites')renderFavoriteContractors();if(id==='contractorPublic')renderContractorPublic();if(id==='workerTeams')renderWorkerTeams();if(id==='workerTeam')renderWorkerTeam();if(id==='groupChat')renderGroupChat();if(id==='workerProfile')renderWorkerProfile();if(id==='editWorkerProfile')fillWorkerEdit();if(id==='rankings')renderRanking(document.querySelector('#rankingTabs .tab.active'));if(id==='publicWorker')renderPublicWorker();if(id==='contractorHome')renderContractorHome();if(id==='contractorShifts')renderContractorShifts();if(id==='shiftManage')renderManageShift();if(id==='applicants')renderApplicants();if(id==='candidateChat')renderCandidateChat();if(id==='contractorTeam')renderContractorTeam();if(id==='contractorGroupChat')renderContractorGroupChat();if(id==='contractorFavorites')renderFavoriteWorkers();if(id==='contractorProfile')renderContractorProfile()}
function enterRole(role){state.pendingRole=role;if(!state.registered){$('regRoleText').textContent=role==='worker'?'Исполнитель':'Подрядчик';$('companyField').style.display=role==='contractor'?'block':'none';$('ageField').style.display=role==='worker'?'block':'none';$('regBenefits').innerHTML=role==='worker'?'<b>Чем полнее профиль — тем больше пользы</b><p>Заполненный профиль выше в поиске, чаще получает приглашения и при 80% открывает статус «Проверенный исполнитель».</p>':'<b>Профиль подрядчика повышает доверие</b><p>Добавьте компанию, фото и контакты: исполнителям проще понять, кто приглашает на смену, а заполненный профиль получает статус «Надёжный подрядчик».</p>';const tg=window.Telegram&&Telegram.WebApp&&Telegram.WebApp.initDataUnsafe&&Telegram.WebApp.initDataUnsafe.user;if(tg&&!$('regName').value)$('regName').value=tg.first_name||'';go('register')}else{state.role=role;saveState();go(role==='worker'?'workerHome':'contractorHome')}}
function previewPhoto(inp,target){const f=inp.files&&inp.files[0];if(!f)return;const r=new FileReader();r.onload=e=>{tempPhotoData=e.target.result;$(target).innerHTML=`<img src="${tempPhotoData}">`};r.readAsDataURL(f)}
function finishRegistration(){let role=state.pendingRole||'worker',name=$('regName').value.trim()||'Пользователь',city=$('regCity').value.trim()||'Москва';if(role==='worker'){Object.assign(state.profile,{name,city,age:$('regAge').value.trim(),phone:$('regPhone').value.trim(),bio:$('regBio').value.trim()});if(tempPhotoData)state.profile.avatar=tempPhotoData}else{Object.assign(state.contractorProfile,{name,company:$('regCompany').value.trim()||name,city,phone:$('regPhone').value.trim(),bio:$('regBio').value.trim()});if(tempPhotoData)state.contractorProfile.avatar=tempPhotoData}state.registered=true;state.role=role;tempPhotoData='';saveState();toast('Профиль создан');navStack=[];go(role==='worker'?'workerHome':'contractorHome',false)}
