function profileCompletion(p){let fields=[p.name,p.city,p.phone,p.bio,p.avatar,p.languages,(p.skills||[]).length,p.experience,(p.docs||[]).length,(p.licenses||[]).length];return Math.round(fields.filter(x=>x&&x!==0).length/fields.length*100)}function contractorCompletion(p){let fields=[p.name,p.company,p.city,p.phone,p.bio,p.avatar];return Math.round(fields.filter(Boolean).length/fields.length*100)}function avatarHTML(name,img,big=false){return img?`<div class="${big?'bigava':'ava'}"><img src="${img}"></div>`:`<div class="${big?'bigava':'ava'}">${(name||'?').slice(0,1).toUpperCase()}</div>`}
function jobMiniCard(j,button='Открыть'){return `<div class="job"><div class="jobhead"><div><h3>${j.title}</h3><div class="muted">${j.company} · ${j.place}</div></div><div class="pay">${fmtMoney(j.pay)}<small>за смену</small></div></div><div class="chips section"><span class="chip">${dateLabel(j.offset)}</span><span class="chip">${j.time}</span><span class="chip">${j.dist} км</span></div><button class="mini ok section" onclick="openDeckAt('${j.id}')">${button}</button></div>`}
function renderWorkerHome(){$('workerHello').textContent='Привет, '+(state.profile.name||'');let pending=state.applications.filter(a=>a.status==='waiting').length,pct=profileCompletion(state.profile);$('pendingCountHome').textContent=pending+' '+plural(pending,'отклик','отклика','откликов');$('profilePctHome').textContent='Профиль '+pct+'%';$('workerHomeJobs').innerHTML=jobs.slice(0,2).map(j=>jobMiniCard(j)).join('');$('workerProfileReminder').innerHTML=(!state.profileReminderDismissed&&pct<100)?`<div class="notice section"><div class="between"><b>Советуем заполнить профиль</b><button class="mini" onclick="dismissProfileReminder()">×</button></div><p>Полный профиль чаще получает приглашения и выше показывается подрядчикам.</p><button class="mini ok" onclick="go('editWorkerProfile')">Заполнить профиль</button></div>`:''}
