function chooseDate(btn){document.querySelectorAll('#dateChips .chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');state.filters.date=btn.dataset.value;saveState()}function chooseLoc(btn){document.querySelectorAll('#locChips .chip[data-value]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');state.filters.loc=btn.dataset.value;saveState()}function chooseCategory(btn){document.querySelectorAll('#catChips .chip').forEach(x=>x.classList.remove('active'));btn.classList.add('active');state.filters.cat=btn.dataset.value;saveState()}
function toggleAnyPay(){state.filters.anyPay=!state.filters.anyPay;$('anyPayBtn').classList.toggle('active',state.filters.anyPay);$('payControls').classList.toggle('dim',state.filters.anyPay);saveState()}function payText(v){v=Number(v);return v>=15000?'от 15 000 ₽+':'от '+v.toLocaleString('ru-RU')+' ₽'}function changePayRange(v){state.filters.minPay=Number(v);state.filters.anyPay=false;$('anyPayBtn').classList.remove('active');$('payControls').classList.remove('dim');$('payLabel').textContent=payText(v);$('payManual').value='';saveState()}function changePayManual(v){let n=Number(v);if(!n)return;state.filters.minPay=n;state.filters.anyPay=false;$('anyPayBtn').classList.remove('active');$('payControls').classList.remove('dim');$('payLabel').textContent=payText(n);if(n>=450&&n<=15000)$('payRange').value=n;saveState()}
function syncFilters(){$('searchCity').value=state.filters.city||state.profile.city||'Москва';$('anyPayBtn').classList.toggle('active',!!state.filters.anyPay);$('payControls').classList.toggle('dim',!!state.filters.anyPay);$('payRange').value=Math.min(15000,Math.max(450,state.filters.minPay||450));$('payLabel').textContent=payText(state.filters.minPay||450)}function useMyLocation(){if(!navigator.geolocation){toast('Геолокация недоступна');return}toast('Запрашиваем геолокацию…');navigator.geolocation.getCurrentPosition(()=>toast('Будем показывать смены рядом с вами'),()=>toast('Не удалось получить геолокацию'))}
function filteredJobs(){state.filters.city=$('searchCity')?($('searchCity').value.trim()||state.filters.city):state.filters.city;let q=($('jobSearchText')&&$('jobSearchText').value||'').trim().toLowerCase();let arr=jobs.filter(j=>{if(!state.filters.anyPay&&j.pay<Number(state.filters.minPay||0))return false;if(state.filters.cat!=='any'&&j.cat!==state.filters.cat)return false;if(q&&!(j.title+' '+j.company+' '+j.desc).toLowerCase().includes(q))return false;return true});saveState();return arr}
function openDeckFromFilters(){deckIds=filteredJobs().map(j=>j.id);if(!deckIds.length){toast('По этим фильтрам смен не найдено');return}deckIndex=0;deckMode='all';lastAction=null;go('deck')}function goNearbyDeck(){deckIds=[...jobs].sort((a,b)=>a.dist-b.dist).map(j=>j.id);deckIndex=0;deckMode='near';lastAction=null;go('deck')}
function changeRadius(v){v=Number(v);state.filters.radius=v;saveState();$('radiusText').textContent=v+' км';$('mapSub').textContent='Химки · '+v+' км';let size=80+v*12;$('radiusCircle').style.width=size+'px';$('radiusCircle').style.height=size+'px';let count=0;document.querySelectorAll('.pin[data-dist]').forEach(p=>{let ok=Number(p.dataset.dist)<=v;p.classList.toggle('hidden',!ok);if(ok)count++});$('mapCount').textContent='В этой области: '+count+' '+plural(count,'смена','смены','смен')}
function openDeckFromMap(){let r=Number(state.filters.radius||8);deckIds=jobs.filter(j=>j.dist<=r).map(j=>j.id);if(!deckIds.length){toast('В этом радиусе пока нет смен');return}deckIndex=0;deckMode='map';lastAction=null;go('deck')}function openJobFromMap(id){deckIds=[id,...jobs.filter(j=>j.id!==id).map(j=>j.id)];deckIndex=0;deckMode='map';lastAction=null;go('deck')}function openDeckAt(id){deckIds=[id,...jobs.filter(j=>j.id!==id).map(j=>j.id)];deckIndex=0;deckMode='all';lastAction=null;go('deck')}function currentJob(){return jobs.find(j=>j.id===deckIds[deckIndex])}
function renderDeck(){$('deckTitle').textContent=deckMode==='similar'?'Похожие смены':'Подходящие смены';$('deckSub').textContent=deckMode==='similar'?'Показываем, почему они похожи':'Свайп вправо — отклик · влево — пропустить';$('undoBar').classList.toggle('show',!!lastAction);if(lastAction)$('undoText').textContent=lastAction.type==='accept'?'Вернуть отклик по прошлой карточке?':'Вернуть пропущенную карточку?';let j=currentJob(),card=$('jobCard');if(!j){card.innerHTML='<div class="emptyStateCard"><div class="icon">⌁</div><h3>Пока новых смен нет</h3><p>Можем показать похожие варианты рядом или изменить параметры поиска.</p><div class="emptyActions"><button class="btn primary" onclick="showFallbackSimilar()">Показать похожие смены</button><button class="btn secondary" onclick="go(\'workerSearch\')">Изменить фильтры</button><button class="mini" onclick="refreshDeck()">Обновить поиск</button></div></div>';return}let fav=state.favoriteContractors.includes(j.contractorId);let why=deckMode==='similar'?'<div class="notice section"><b>Почему похожа</b><p>Та же или близкая сфера, похожая оплата и локация.</p></div>':'';card.className='swipe';card.innerHTML=`<div><div class="row between"><span class="badge ${j.verified?'verified':'worker'}">${j.verified?'✓ Проверенный подрядчик':'Подрядчик'}</span><button class="mini ${fav?'yellow':''}" onclick="event.stopPropagation();toggleFavoriteContractor('${j.contractorId}')">${fav?'★ В избранном':'☆ В избранное'}</button></div><div class="jobhead section"><div><h3 class="jobTitle">${j.title}</h3><button class="mini" onclick="event.stopPropagation();openContractor('${j.contractorId}')">${j.company} · профиль</button><div class="muted section tiny">${j.place}</div></div><div class="pay">${fmtMoney(j.pay)}<small>за смену</small></div></div><div class="chips section"><span class="chip">${dateLabel(j.offset)}</span><span class="chip">${j.time}</span><span class="chip">${j.dist} км</span><span class="chip ratingChip"><b>★</b> ${j.rating}</span></div><div class="descriptionBox"><b>Описание смены</b><p>${j.desc}</p></div>${why}</div><div><button class="btn secondary full" onclick="event.stopPropagation();findSimilar()">Найти похожие</button><div class="swipebuttons section"><button class="round no" onclick="event.stopPropagation();actCard('skip')">×</button><button class="round yes" onclick="event.stopPropagation();actCard('accept')">✓</button></div><div class="muted swipeHint">← пропустить · вправо отклик →</div></div>`;attachSwipe(card)}
function attachSwipe(card){let startX=0,dx=0,drag=false;card.onpointerdown=e=>{if(e.target.closest('button'))return;drag=true;startX=e.clientX;card.classList.add('dragging');try{card.setPointerCapture(e.pointerId)}catch(_){}};card.onpointermove=e=>{if(!drag)return;dx=e.clientX-startX;card.style.transform=`translateX(${dx}px) rotate(${dx/18}deg)`;$('stampYes').style.opacity=Math.max(0,dx/90);$('stampNo').style.opacity=Math.max(0,-dx/90)};card.onpointerup=e=>{if(!drag)return;drag=false;card.classList.remove('dragging');if(dx>85)actCard('accept');else if(dx<-85)actCard('skip');else{card.style.transform='';$('stampYes').style.opacity=0;$('stampNo').style.opacity=0}dx=0};card.onpointercancel=card.onpointerup}
function actCard(type){let j=currentJob();if(!j)return;lastAction={type,jobId:j.id,index:deckIndex,similarBase:j.id};if(type==='accept'){if(!state.applications.some(a=>a.jobId===j.id))state.applications.push({jobId:j.id,status:'waiting'});toast('Отклик отправлен · смена добавлена в «Мои смены»')}else{if(!state.discarded.includes(j.id))state.discarded.push(j.id);toast('Смена пропущена')}saveState();let card=$('jobCard');card.classList.add(type==='accept'?'outRight':'outLeft');$('stampYes').style.opacity=0;$('stampNo').style.opacity=0;setTimeout(()=>{deckIndex++;renderDeck()},180)}function undoLast(){if(!lastAction)return;if(lastAction.type==='accept')state.applications=state.applications.filter(a=>a.jobId!==lastAction.jobId);if(lastAction.type==='skip')state.discarded=state.discarded.filter(id=>id!==lastAction.jobId);deckIndex=lastAction.index;lastAction=null;saveState();renderDeck();toast('Карточка возвращена')}
function findSimilar(){let base=currentJob();if(!base)return;let score=j=>(j.cat===base.cat?3:0)+(Math.abs(j.pay-base.pay)<=1500?2:0)+(j.city===base.city?1:0)+(Math.abs(j.dist-base.dist)<=5?1:0);let arr=jobs.filter(j=>j.id!==base.id).map(j=>[j,score(j)]).filter(x=>x[1]>=2).sort((a,b)=>b[1]-a[1]).map(x=>x[0].id);if(!arr.length){toast('Похожих смен пока нет');return}lastAction={type:'similar',jobId:base.id,index:0,similarBase:base.id};deckIds=arr;deckIndex=0;deckMode='similar';renderDeck();toast('Подобрали похожие смены')}
function toggleFavoriteContractor(id){let i=state.favoriteContractors.indexOf(id);if(i>=0)state.favoriteContractors.splice(i,1);else state.favoriteContractors.push(id);saveState();renderDeck();toast(i>=0?'Удалено из избранного':'Подрядчик добавлен в избранное')}
function showWorkerShiftTab(btn){document.querySelectorAll('#workerShiftTabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');activeWorkerShiftTab=btn.dataset.status;renderWorkerShifts()}function workerShiftItems(status){let arr=[];state.applications.forEach(a=>{if(a.status===status){let j=jobs.find(x=>x.id===a.jobId);if(j)arr.push({j,status})}});if(status==='confirmed')state.confirmed.forEach(a=>{let j=jobs.find(x=>x.id===a.jobId);if(j&&!arr.some(x=>x.j.id===j.id))arr.push({j,status:'confirmed'})});if(status==='rejected')state.rejected.forEach(a=>{let j=jobs.find(x=>x.id===a.jobId);if(j&&!arr.some(x=>x.j.id===j.id))arr.push({j,status:'rejected'})});return arr}
function renderWorkerShifts(){let items=workerShiftItems(activeWorkerShiftTab),el=$('workerShiftList');if(!items.length){el.innerHTML=`<div class="empty"><div class="icon">◌</div><b>Здесь пока пусто</b><div>${activeWorkerShiftTab==='waiting'?'Откликнитесь на смену — она появится здесь.':'Когда статус изменится, смена появится в этом разделе.'}</div></div>`;return}el.innerHTML=items.map(({j,status})=>`<div class="job"><div class="jobhead"><div><h3>${j.title}</h3><div class="muted">${j.company} · ${j.place}</div></div><span class="badge ${status==='waiting'?'wait':status==='confirmed'?'ok':'rejected'}">${status==='waiting'?'В ожидании':status==='confirmed'?'Подтверждена':'Отклонена'}</span></div><div class="chips section"><span class="chip">${dateLabel(j.offset)}</span><span class="chip">${j.time}</span><span class="chip">${fmtMoney(j.pay)}</span></div><div class="row section">${status==='confirmed'?`<button class="btn primary" onclick="openWorkerTeam('${j.id}')">Команда и чат</button>`:''}${status==='waiting'?`<button class="btn secondary" onclick="cancelApplication('${j.id}')">Отменить отклик</button>`:''}</div></div>`).join('')}function cancelApplication(id){state.applications=state.applications.filter(a=>a.jobId!==id);saveState();renderWorkerShifts();toast('Отклик отменён')}
function renderFavoriteContractors(){let el=$('favoriteContractorList'),ids=state.favoriteContractors;if(!ids.length){el.innerHTML='<div class="empty"><div class="icon">☆</div><b>Избранных подрядчиков пока нет</b><div>Добавляйте их из карточек смен.</div></div>';return}el.innerHTML=ids.map(id=>{let c=contractors[id];return `<div class="person">${avatarHTML(c.name,'')}<div class="grow"><h4>${c.name} ${c.verified?'<span class="badge verified">✓ проверен</span>':''}</h4><small>★ ${c.rating} · ${c.reviews} отзывов</small><div class="minirow"><button class="mini ok" onclick="openContractor('${id}')">Посмотреть объявления</button><button class="mini" onclick="removeFavContractor('${id}')">Убрать</button></div></div></div>`}).join('')}function removeFavContractor(id){state.favoriteContractors=state.favoriteContractors.filter(x=>x!==id);saveState();renderFavoriteContractors()}function openContractor(id){state.selectedContractor=id;saveState();go('contractorPublic')}
function renderContractorPublic(){let c=contractors[state.selectedContractor]||contractors.c1;let js=(c.jobs||[]).map(id=>jobs.find(j=>j.id===id)).filter(Boolean);$('contractorPublicBody').innerHTML=`<div class="card"><div class="profiletop">${avatarHTML(c.name,'',true)}<div><h2 class="noMargin">${c.name}</h2>${c.verified?'<div class="verify">✓ Проверенный подрядчик</div>':''}<div class="muted tiny">★ ${c.rating} · ${c.reviews} отзывов</div></div></div><p class="meta section">${c.about}</p><button class="btn ${state.favoriteContractors.includes(c.id)?'secondary':'primary'}" onclick="toggleFavFromProfile('${c.id}')">${state.favoriteContractors.includes(c.id)?'★ В избранном':'☆ Добавить в избранное'}</button></div><div class="title"><h2>Актуальные объявления</h2><span>${js.length}</span></div>${js.length?js.map(j=>jobMiniCard(j,'Открыть смену')).join('<div class="section"></div>'):'<div class="empty"><b>У этого подрядчика нет актуальных смен</b><div>Загляните позже — профиль останется в избранном.</div></div>'}`}function toggleFavFromProfile(id){if(state.favoriteContractors.includes(id))state.favoriteContractors=state.favoriteContractors.filter(x=>x!==id);else state.favoriteContractors.push(id);saveState();renderContractorPublic()}
function openWorkerTeam(id){state.selectedTeamShift=id;saveState();go('workerTeam')}function renderWorkerTeams(){let ids=state.confirmed.map(x=>x.jobId),el=$('workerTeamList');if(!ids.length){el.innerHTML='<div class="empty"><div class="icon">👥</div><b>Команда появится после подтверждения на смену</b><div>Пока подрядчик не принял ваш отклик, раздел не нужен.</div></div>';return}el.innerHTML=ids.map(id=>{let j=jobs.find(x=>x.id===id);return `<div class="job"><h3>${j.title}</h3><div class="muted">${j.company} · ${dateLabel(j.offset)} · ${j.time}</div><button class="btn primary section" onclick="openWorkerTeam('${id}')">Открыть команду</button></div>`}).join('')}
function renderWorkerTeam(){let j=jobs.find(x=>x.id===state.selectedTeamShift)||jobs[1];$('workerTeamTitle').textContent=j.title;$('workerTeamSub').textContent=j.company+' · '+dateLabel(j.offset);$('workerTeamSummary').innerHTML=`<b>${j.place}</b><div class="muted tiny section">${j.time} · ${fmtMoney(j.pay)}</div><div class="notice section"><b>Вы приняты на смену</b><p>В этом разделе только информация вашей команды и общий чат. Управление сменой доступно подрядчику.</p></div>`;$('workerTeamCount').textContent='6 участников';$('workerTeamMembers').innerHTML=`<div class="person">${avatarHTML('Сергей','')}<div class="grow"><h4>Сергей <span class="badge contractor">подрядчик</span></h4><small>Создатель смены</small></div></div><div class="person">${avatarHTML('Александр','')}<div class="grow"><h4>Александр <span class="badge admin">старший</span></h4><small>Помогает координировать команду</small></div></div><div class="person">${avatarHTML(state.profile.name,state.profile.avatar)}<div class="grow"><h4>${state.profile.name} <span class="badge worker">исполнитель</span></h4><small>Подтвердил участие</small></div></div>`}
function renderGroupChat(){let j=jobs.find(x=>x.id===state.selectedTeamShift)||jobs[1];$('groupChatTitle').textContent='Чат · '+j.title;$('groupChatMessages').innerHTML=state.groupMessages.map(m=>`<div class="msg ${m.who===state.profile.name?'me':''}"><div class="who ${m.role||''}">${m.who}${m.role==='contractor'?' · подрядчик':m.role==='admin'?' · старший':''}</div>${m.text}</div>`).join('')}function sendGroupMessage(){let i=$('groupChatInput'),t=i.value.trim();if(!t)return;state.groupMessages.push({who:state.profile.name,role:'worker',text:t});i.value='';saveState();renderGroupChat()}
function renderWorkerProfile(){let p=state.profile,pct=profileCompletion(p),verified=pct>=80,skillParts=[];if((p.licenses||[]).length)skillParts.push('Права '+p.licenses.join(','));if(p.gearbox)skillParts.push(p.gearbox);if(p.driveYears)skillParts.push('Вождение '+p.driveYears);if(p.experience)skillParts.push(p.experience);(p.skills||[]).forEach(x=>skillParts.push(x));let docs=(p.docs||[]);$('workerProfileBody').innerHTML=`<div class="card"><div class="profiletop">${avatarHTML(p.name,p.avatar,true)}<div><h2 class="noMargin">${p.name||'Пользователь'}</h2>${verified?'<div class="verify">✓ Проверенный исполнитель</div>':''}<div class="muted tiny">${p.city||''}${p.age?' · '+p.age+' года':''}</div></div></div><div class="completeBar"><div class="progressline"><b>Профиль ${pct}%</b><span class="muted">${pct>=100?'Заполнен полностью':'Можно усилить'}</span></div><div class="progress"><i style="width:${pct}%"></i></div></div>${pct<100?`<div class="notice section"><b>Заполните профиль до 100%</b><p>Выше в поиске, больше приглашений и больше доверия подрядчиков. Статус «Проверенный исполнитель» появляется с 80%.</p><button class="mini ok" onclick="go('editWorkerProfile')">Продолжить</button></div>`:''}<button class="btn secondary section" onclick="go('editWorkerProfile')">Редактировать профиль</button></div><div class="grid2 section"><button class="choice action" onclick="go('speedScore')"><span class="muted">Speed Score</span><b class="score">97</b><small>Как считается →</small></button><button class="choice action" onclick="go('rankings')"><span class="muted">Рейтинг августа</span><b>#18</b><small>Открыть рейтинг →</small></button></div><div class="title"><h2>Навыки и опыт</h2><span>только указанное</span></div>${skillParts.length?`<div class="chips">${skillParts.map(x=>`<span class="chip">${x}</span>`).join('')}</div>`:'<div class="empty"><b>Навыки пока не указаны</b></div>'}<div class="title"><h2>Достижения</h2><span>мотивация</span></div><div class="grid2"><div class="choice"><b>30 без опозданий</b><small>серия</small></div><div class="choice"><b>★ 4.9</b><small>42 смены</small></div><div class="choice"><b>12 раз</b><small>добавили в избранное</small></div><div class="choice"><b>Топ-15 · Сентябрь</b><small>Лучший результат</small></div></div><div class="title"><h2>Документы</h2><span>только добавленные</span></div>${docs.length?`<div class="chips">${docs.map(x=>`<span class="chip active">${x} ✓</span>`).join('')}</div><p class="help section">Подрядчик получает документ только после отдельного запроса и вашего разрешения.</p>`:'<div class="empty"><b>Документы пока не добавлены</b></div>'}<div class="row section"><button class="btn secondary" onclick="go('workerTeams')">Мои команды</button><button class="btn secondary" onclick="go('settings')">Настройки</button></div>`}
function fillWorkerEdit(){let p=state.profile;$('epName').value=p.name||'';$('epAge').value=p.age||'';$('epCity').value=p.city||'';$('epPhone').value=p.phone||'';$('epBio').value=p.bio||'';$('epLanguages').value=p.languages||'';$('epSkills').value=(p.skills||[]).join(', ');$('epExperience').value=p.experience||'';$('epDriveYears').value=p.driveYears||'';$('epGearbox').value=p.gearbox||'';$('epPhotoPreview').innerHTML=p.avatar?`<img src="${p.avatar}">`:(p.name||'?').slice(0,1).toUpperCase();document.querySelectorAll('#licenseChips .chip').forEach(x=>x.classList.toggle('active',(p.licenses||[]).includes(x.dataset.value)));document.querySelectorAll('#docChips .chip').forEach(x=>x.classList.toggle('active',(p.docs||[]).includes(x.dataset.value)))}function activeValues(selector){return [...document.querySelectorAll(selector+' .chip.active')].map(x=>x.dataset.value)}function saveWorkerProfile(){let p=state.profile;p.name=$('epName').value.trim();p.age=$('epAge').value.trim();p.city=$('epCity').value.trim();p.phone=$('epPhone').value.trim();p.bio=$('epBio').value.trim();p.languages=$('epLanguages').value.trim();p.skills=$('epSkills').value.split(',').map(x=>x.trim()).filter(Boolean);p.experience=$('epExperience').value.trim();p.driveYears=$('epDriveYears').value.trim();p.gearbox=$('epGearbox').value;p.licenses=activeValues('#licenseChips');p.docs=activeValues('#docChips');if(tempPhotoData)p.avatar=tempPhotoData;tempPhotoData='';saveState();toast('Профиль сохранён');go('workerProfile')}function toggleMulti(btn){btn.classList.toggle('active')}
function renderRanking(btn){if(btn){document.querySelectorAll('#rankingTabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}let type=(btn&&btn.dataset.rank)||'shifts',arr=[...rankingPeople];arr.sort((a,b)=>type==='shifts'?b.shifts-a.shifts:type==='rating'?b.rating-a.rating:b.punctual-a.punctual);$('rankingList').innerHTML=arr.map((p,i)=>`<button class="rankRow" onclick="openPublicWorker('${p.name}')"><div class="rankNo ${i<3?'top':''}">${i+1}</div>${avatarHTML(p.name,'')}<div class="grow"><b>${p.name}</b><div class="muted tiny">${type==='shifts'?p.shifts+' смен':type==='rating'?'★ '+p.rating:p.punctual+'% вовремя'}</div></div><span>›</span></button>`).join('')}function openPublicWorker(name){state.selectedWorker=name;saveState();go('publicWorker')}function renderPublicWorker(){let p=rankingPeople.find(x=>x.name===state.selectedWorker)||rankingPeople[0];$('publicWorkerBody').innerHTML=`<div class="card"><div class="profiletop">${avatarHTML(p.name,'',true)}<div><h2 class="noMargin">${p.name}</h2><div class="verify">✓ Проверенный исполнитель</div><div class="muted tiny">★ ${p.rating} · ${p.shifts} смен</div></div></div><div class="chips section">${p.skills.map(x=>`<span class="chip">${x}</span>`).join('')}</div></div>`}
function renderContractorHome(){let p=state.contractorProfile,pct=contractorCompletion(p);$('contractorHello').textContent=(p.company||'Панель подрядчика');$('contractorPctHome').textContent='Профиль '+pct+'%';$('contractorProfileReminder').innerHTML=(!state.contractorReminderDismissed&&pct<100)?`<div class="notice section"><div class="between"><b>Заполните профиль подрядчика</b><button class="mini" onclick="dismissContractorReminder()">×</button></div><p>Фото, компания и контакты повышают доверие исполнителей.</p></div>`:'';let s=state.createdShifts[0];$('contractorHomeShift').innerHTML=contractorShiftCard(s)}
function dismissContractorReminder(){state.contractorReminderDismissed=true;saveState();renderContractorHome()}function contractorShiftCard(s){let pct=Math.min(100,Math.round(s.filled/s.needed*100));return `<div class="job"><div class="jobhead"><div><h3>${s.title}</h3><div class="muted">${s.city} · ${dateLabel(s.offset)} · ${s.time}</div></div><div class="pay">${fmtMoney(s.pay)}<small>человеку</small></div></div><div class="progressline section"><b>${s.filled} из ${s.needed}</b><span class="muted">набрано</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="row section"><button class="btn secondary" onclick="openManageShift('${s.id}')">Управлять</button><button class="btn outline" onclick="recruitMore('${s.id}')">Добрать людей</button></div></div>`}
function publishShift(){let req=activeValues('#reqChips'),title=$('csTitle').value.trim(),pay=Number($('csPay').value||0),needed=Number($('csPeople').value||1);if(!title||!pay){toast('Заполните название и оплату');return}let id='s'+Date.now();state.createdShifts.unshift({id,title,city:$('csCity').value.trim()||'Москва',offset:1,time:$('csTime').value.trim(),pay,needed,filled:0,address:$('csAddress').value.trim(),status:'recruiting',requirements:req,desc:$('csDesc').value.trim()});state.currentShift=id;saveState();toast('Смена опубликована');go('contractorShifts')}function renderContractorShifts(){$('contractorShiftList').innerHTML=state.createdShifts.map(contractorShiftCard).join('')}function openManageShift(id){state.currentShift=id;saveState();go('shiftManage')}function getCurrentShift(){return state.createdShifts.find(x=>x.id===state.currentShift)||state.createdShifts[0]}
function renderManageShift(){let s=getCurrentShift(),pct=Math.min(100,Math.round(s.filled/s.needed*100));$('manageTitle').textContent=s.title;$('manageSub').textContent=s.city+' · '+dateLabel(s.offset);$('manageBody').innerHTML=`<div class="card"><div class="progressline"><b>${s.filled} из ${s.needed}</b><span class="muted">${s.filled>=s.needed?'Команда собрана':'Команда набирается'}</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="row section"><button class="btn secondary" onclick="changeShiftPeople('${s.id}')">Изменить условия</button><button class="btn outline" onclick="recruitMore('${s.id}')">Добрать людей</button></div>${s.filled>=s.needed?`<button class="btn primary full section" onclick="confirmStartShift('${s.id}')">Начать смену</button>`:`<div class="help section">Кнопка «Начать смену» появится, когда команда будет собрана.</div>`}</div>`}
function changeShiftPeople(id){let s=state.createdShifts.find(x=>x.id===id),n=prompt('Сколько людей нужно на смену?',s.needed);if(n===null)return;n=Number(n);if(!n||n<1)return;if(n<s.filled){openConfirm('Уменьшить число мест?',`Сейчас принято ${s.filled} человек. Система не удалит никого автоматически — сначала решите, кого снять со смены.`,()=>toast('Сначала измените состав команды'))}else{s.needed=n;saveState();renderManageShift();toast('Количество мест обновлено')}}function recruitMore(){toast('Приглашения отправлены подходящим исполнителям по навыкам, локации и доступности')}function confirmStartShift(){openConfirm('Начать смену?','Всем участникам придёт уведомление, что смена началась.',()=>toast('Смена началась'))}
function renderApplicants(){$('applicantList').innerHTML=candidates.map(c=>{let st=state.candidateStatus[c.id]||'new';return `<div class="person">${avatarHTML(c.name,'')}<div class="grow"><h4>${c.name} ${st==='accepted'?'<span class="badge ok">принят</span>':st==='rejected'?'<span class="badge rejected">отклонён</span>':''}</h4><small>★ ${c.rating} · ${c.shifts} смен · ${c.skills.join(' · ')}</small><div class="minirow">${st==='new'?`<button class="mini ok" onclick="selectCandidate('${c.id}');confirmApplicant('accept')">Принять</button><button class="mini no" onclick="selectCandidate('${c.id}');confirmApplicant('reject')">Отклонить</button>`:''}<button class="mini" onclick="openCandidateChat('${c.id}')">💬 Чат</button></div></div></div>`}).join('')}function selectCandidate(id){activeCandidate=id;state.selectedCandidate=id;saveState()}function openCandidateChat(id){selectCandidate(id);go('candidateChat')}function renderCandidateChat(){let c=candidates.find(x=>x.id===state.selectedCandidate)||candidates[0];activeCandidate=c.id;$('candidateName').textContent=c.name;$('candidateChatName').textContent=c.name;let msgs=(state.candidateMessages&&state.candidateMessages[c.id])||[];$('candidateMessages').innerHTML=msgs.map(m=>`<div class="msg ${m.from==='me'?'me':''}">${m.text}</div>`).join('')}
function confirmApplicant(action){let c=candidates.find(x=>x.id===activeCandidate)||candidates[0],isAccept=action==='accept';openConfirm(isAccept?'Принять исполнителя?':'Отклонить исполнителя?',isAccept?`После подтверждения ${c.name} получит уведомление и доступ к команде этой смены.`:`${c.name} получит статус «Отклонён».`,()=>{state.candidateStatus[c.id]=isAccept?'accepted':'rejected';let s=getCurrentShift();if(isAccept&&s.filled<s.needed)s.filled++;saveState();toast(isAccept?'Исполнитель принят':'Отклик отклонён');if(currentScreen==='candidateChat')renderCandidateChat();else renderApplicants()})}function sendCandidateMessage(){let i=$('candidateInput'),t=i.value.trim();if(!t)return;if(!state.candidateMessages)state.candidateMessages={};if(!state.candidateMessages[activeCandidate])state.candidateMessages[activeCandidate]=[];state.candidateMessages[activeCandidate].push({from:'me',text:t});i.value='';saveState();renderCandidateChat();toast('Сообщение отправлено')}function openDocsRequest(){document.querySelectorAll('#docsRequestChips .chip').forEach(x=>x.classList.remove('active'));openModal('docsModal')}function sendDocsRequest(){let docs=activeValues('#docsRequestChips');if(!docs.length){toast('Выберите документы');return}closeModal('docsModal');toast('Запрос отправлен: '+docs.join(', '))}
function renderContractorTeam(){let s=getCurrentShift(),removed=state.removedTeamMembers||[],members=[['Сергей','contractor','подрядчик'],['Александр','admin','старший'],['Максим','worker','исполнитель'],['Илья','worker','исполнитель'],['Дмитрий','worker','исполнитель']].filter(x=>!removed.includes(x[0]));$('contractorTeamBody').innerHTML=`<div class="card"><div class="progressline"><b>${s.filled} из ${s.needed}</b><span class="muted">${s.title}</span></div><div class="progress"><i style="width:${Math.min(100,s.filled/s.needed*100)}%"></i></div></div><div class="title"><h2>Участники</h2><span>роли</span></div>${members.map(([name,role,label])=>`<div class="person">${avatarHTML(name,'')}<div class="grow"><h4>${name} <span class="badge ${role}">${label}</span></h4><small>${role==='contractor'?'Полный доступ':role==='admin'?'Права настраивает подрядчик':'Принят на смену'}</small><div class="minirow">${role==='admin'?'<button class="mini yellow" onclick="go(\'permissions\')">Настроить права</button>':''}${role==='worker'?`<button class="mini no" onclick="removeTeamMember('${name}')">Удалить</button>`:''}</div></div></div>`).join('')}<button class="btn primary full section" onclick="go('contractorGroupChat')">Открыть общий чат</button>`}
function removeTeamMember(name){openConfirm('Удалить из команды?',`${name} будет снят с этой смены.`,()=>{if(!state.removedTeamMembers)state.removedTeamMembers=[];if(!state.removedTeamMembers.includes(name))state.removedTeamMembers.push(name);let s=getCurrentShift();s.filled=Math.max(0,s.filled-1);saveState();renderContractorTeam();toast('Исполнитель удалён из команды')})}function toggleSwitch(btn){btn.classList.toggle('on')}
function renderContractorGroupChat(){$('contractorGroupMessages').innerHTML=state.contractorGroupMessages.map(m=>`<div class="msg ${m.who===state.contractorProfile.name?'me':''}"><div class="who ${m.role||''}">${m.who}${m.role==='contractor'?' · подрядчик':m.role==='admin'?' · старший':''}</div>${m.text}</div>`).join('')}function sendContractorGroupMessage(){let i=$('contractorGroupInput'),t=i.value.trim();if(!t)return;state.contractorGroupMessages.push({who:state.contractorProfile.name||'Подрядчик',role:'contractor',text:t});i.value='';saveState();renderContractorGroupChat()}
function renderFavoriteWorkers(){$('favoriteWorkerList').innerHTML=state.favoriteWorkers.map(id=>{let c=candidates.find(x=>x.id===id);if(!c)return'';return `<div class="person">${avatarHTML(c.name,'')}<div class="grow"><h4>${c.name}</h4><small>★ ${c.rating} · ${c.shifts} смен · уже работали ${id==='w1'?4:2} раза</small><div class="minirow"><button class="mini ok" onclick="toast('Приглашение на смену отправлено')">Позвать</button><button class="mini" onclick="openPublicWorker('${c.name}')">Профиль</button></div></div></div>`}).join('')}
function renderContractorProfile(){let p=state.contractorProfile,pct=contractorCompletion(p),verified=pct>=80;$('contractorProfileBody').innerHTML=`<div class="card"><div class="profiletop">${avatarHTML(p.company||p.name,p.avatar,true)}<div><h2 class="noMargin">${p.company||p.name}</h2>${verified?'<div class="verify">✓ Надёжный подрядчик</div>':''}<div class="muted tiny">${p.city||''} · ★ 4.9</div></div></div><p class="meta section">${p.bio||'Добавьте информацию о компании.'}</p><div class="completeBar"><div class="progressline"><b>Профиль ${pct}%</b><span class="muted">Компания и контакт</span></div><div class="progress"><i style="width:${pct}%"></i></div></div></div><div class="grid2 section"><div class="choice"><b>98%</b><small>выплат вовремя</small></div><div class="choice"><b>4.9 ★</b><small>оценка исполнителей</small></div><div class="choice"><b>84</b><small>закрытые смены</small></div><div class="choice"><b>6 мин</b><small>средний ответ</small></div></div><div class="row section"><button class="btn secondary" onclick="go('contractorFavorites')">Избранные исполнители</button><button class="btn secondary" onclick="go('settings')">Настройки</button></div>`}
function switchRole(){state.role=state.role==='worker'?'contractor':'worker';saveState();navStack=[];toast('Режим изменён');go(state.role==='worker'?'workerHome':'contractorHome',false)}function resetDemo(){localStorage.removeItem(LS);state=clone(baseState);navStack=[];currentScreen='landing';toast('Демо сброшено');setTimeout(()=>location.reload(),500)}function openConfirm(title,text,cb){pendingConfirm=cb;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmOk').onclick=()=>{closeModal('confirmModal');let f=pendingConfirm;pendingConfirm=null;if(f)f()};openModal('confirmModal')}function openModal(id){$(id).classList.add('show')}function closeModal(id){$(id).classList.remove('show')}function toast(t){let x=$('toast');x.textContent=t;x.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.classList.remove('show'),1800)}

// ===== SPEED HELPER V4 overrides =====
let v4EditingShiftId=null;
function formatPhone(inp){let d=(inp.value||'').replace(/\D/g,'').slice(0,10);let p=[];if(d.length>0)p.push(d.slice(0,3));if(d.length>3)p.push(d.slice(3,6));if(d.length>6)p.push(d.slice(6,8));if(d.length>8)p.push(d.slice(8,10));inp.value=p.join(d.length>6?'-':' ')}
function contractorCompletion(p){let fields=[p.name,p.city,p.phone,p.avatar];return Math.round(fields.filter(Boolean).length/fields.length*100)}
function buildNav(){const n=$('bottomNav');n.innerHTML='';if(!state.registered||!state.role||['groupChat','contractorGroupChat','candidateChat'].includes(currentScreen)){n.style.display='none';return}n.style.display='grid';let items=state.role==='worker'?[['workerHome','⌂','Главная'],['workerSearch','⌕','Поиск'],['workerShifts','✓','Смены'],['workerFavorites','★','Избранное'],['workerProfile','●','Профиль']]:[['contractorHome','⌂','Главная'],['createShift','＋','Создать'],['contractorShifts','▤','Смены'],['applicants','◌','Отклики'],['contractorProfile','●','Профиль']];items.forEach(([id,ico,label])=>{let b=document.createElement('button');b.dataset.go=id;b.innerHTML=`<span>${ico}</span>${label}`;b.onclick=()=>id==='createShift'?openCreateShift():go(id);if(id===currentScreen)b.classList.add('active');n.appendChild(b)})}
function enterRole(role){state.pendingRole=role;if(!state.registered){$('regRoleText').textContent=role==='worker'?'Исполнитель':'Подрядчик';$('companyField').style.display=role==='contractor'?'block':'none';$('ageField').style.display=role==='worker'?'block':'none';$('regBenefits').innerHTML=role==='worker'?'<div class="trustLead"><span class="trustCheck">✓</span><b>Чем полнее профиль — тем больше пользы</b></div><p>Заполненный профиль выше в поиске, чаще получает приглашения и при 80% открывает статус «Проверенный исполнитель».</p>':'<div class="trustLead"><span class="trustCheck">✓</span><b>Профиль подрядчика повышает доверие</b></div><p><strong>Добавьте фото и контакт.</strong> Исполнителям будет проще сразу понять, кто открывает смену. Имя компании и описание можно заполнить позже.</p>';let tg=window.Telegram&&Telegram.WebApp&&Telegram.WebApp.initDataUnsafe&&Telegram.WebApp.initDataUnsafe.user;if(tg&&!$('regName').value)$('regName').value=tg.first_name||'';go('register')}else{state.role=role;saveState();go(role==='worker'?'workerHome':'contractorHome')}}
function finishRegistration(){let role=state.pendingRole||'worker',name=$('regName').value.trim()||'Пользователь',city=$('regCity').value.trim()||'Москва',phoneDigits=$('regPhone').value.replace(/\D/g,'');let phone=phoneDigits?'+7 '+$('regPhone').value.trim():'';if(role==='worker'){Object.assign(state.profile,{name,city,age:$('regAge').value.trim(),phone,bio:$('regBio').value.trim()});if(tempPhotoData)state.profile.avatar=tempPhotoData}else{Object.assign(state.contractorProfile,{name,company:$('regCompany').value.trim(),city,phone,bio:$('regBio').value.trim()});if(tempPhotoData)state.contractorProfile.avatar=tempPhotoData}state.registered=true;state.role=role;tempPhotoData='';saveState();toast('Профиль создан');navStack=[];go(role==='worker'?'workerHome':'contractorHome',false)}
function renderContractorHome(){let p=state.contractorProfile,pct=contractorCompletion(p),active=state.createdShifts.filter(s=>s.status!=='deleted'),newApps=Object.values(state.candidateStatus||{}).filter(x=>x==='new').length;$('contractorHello').textContent=(p.company||p.name||'Панель подрядчика');$('contractorPctHome').textContent='Профиль '+pct+'%';$('activeShiftCount').textContent=active.length;$('newApplicantCount').textContent=newApps;$('favoriteWorkerCount').textContent=(state.favoriteWorkers||[]).length;$('contractorProfileReminder').innerHTML=(!state.contractorReminderDismissed&&pct<100)?`<div class="notice section"><div class="between"><b>✓ Заполните профиль подрядчика</b><button class="mini" onclick="dismissContractorReminder()">×</button></div><p>Фото и контакт повышают доверие исполнителей и делают профиль заметнее.</p></div>`:'';let s=active[0];$('contractorHomeShift').innerHTML=s?contractorShiftCard(s):`<div class="emptyStateCard"><div class="icon">＋</div><h3>У вас пока нет открытых смен</h3><p>Создайте первую смену — здесь появятся набор, прогресс и быстрые действия.</p><button class="btn primary full section" onclick="openCreateShift()">Создать смену</button></div>`}
function contractorShiftCard(s){if(!s)return'';let pct=Math.min(100,Math.round((s.filled||0)/(s.needed||1)*100));return `<div class="job activeShiftCard"><div class="jobhead"><div><h3>${s.title}</h3><div class="shiftDateLine">${s.city} · ${dateLabel(s.offset)}</div><div class="shiftTimeLine">${s.time||'Время не указано'}</div></div><div class="pay">${fmtMoney(s.pay)}<small>человеку</small></div></div><div class="progressline section"><b>${s.filled||0} из ${s.needed}</b><span class="muted">набрано</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="row section"><button class="btn secondary" onclick="openManageShift('${s.id}')">Управлять</button><button class="btn outline" onclick="recruitMore('${s.id}')">Добрать людей</button></div></div>`}
function renderContractorShifts(){let arr=state.createdShifts.filter(s=>s.status!=='deleted');$('contractorShiftList').innerHTML=arr.length?arr.map(contractorShiftCard).join(''):`<div class="emptyStateCard"><div class="icon">▤</div><h3>Смен пока нет</h3><p>Создайте первую смену — после публикации она появится здесь.</p><button class="btn primary full section" onclick="openCreateShift()">Создать смену</button></div>`}
function getCurrentShift(){return state.createdShifts.find(x=>x.id===state.currentShift&&x.status!=='deleted')||state.createdShifts.find(x=>x.status!=='deleted')||null}
function openCreateShift(editId=null){v4EditingShiftId=editId;go('createShift');let s=editId?state.createdShifts.find(x=>x.id===editId):null;if(s){$('csTitle').value=s.title||'';$('csPay').value=s.pay||'';$('csPeople').value=s.needed||'';$('csCity').value=s.city||'';$('csAddress').value=s.address||'';$('csTime').value=s.time||'';$('csDesc').value=s.desc||'';document.querySelectorAll('#reqChips .chip').forEach(x=>x.classList.toggle('active',(s.requirements||[]).includes(x.dataset.value)));document.querySelector('#createShift .pagebar h1').textContent='Изменить смену';document.querySelector('#createShift .pagebar .sub').textContent='Изменения увидят откликнувшиеся';document.querySelector('#createShift .form>.btn.primary:last-child').textContent='Сохранить изменения'}else{document.querySelector('#createShift .pagebar h1').textContent='Создать смену';document.querySelector('#createShift .pagebar .sub').textContent='Подрядчик';document.querySelector('#createShift .form>.btn.primary:last-child').textContent='Опубликовать смену';$('csTitle').value='';$('csPay').value='';$('csPeople').value='';$('csCity').value=state.contractorProfile.city||'Москва';$('csAddress').value='';$('csTime').value='09:00–18:00';$('csDesc').value='';document.querySelectorAll('#reqChips .chip').forEach(x=>x.classList.remove('active'));$('csDate').value=new Date(Date.now()+86400000).toISOString().slice(0,10)}}
function publishShift(){let req=activeValues('#reqChips'),title=$('csTitle').value.trim(),pay=Number($('csPay').value||0),needed=Number($('csPeople').value||1),city=$('csCity').value.trim()||'Москва',time=$('csTime').value.trim(),address=$('csAddress').value.trim(),desc=$('csDesc').value.trim();if(!title||!pay){toast('Заполните название и оплату');return}if(v4EditingShiftId){let s=state.createdShifts.find(x=>x.id===v4EditingShiftId);if(!s){v4EditingShiftId=null;return}let major=(s.title!==title||s.city!==city);let applyUpdate=()=>{Object.assign(s,{title,city,time,pay,needed,address,requirements:req,desc});saveState();v4EditingShiftId=null;toast('Условия смены обновлены');go('shiftManage')};if(major){openConfirm('Создать новую смену?', 'Вы изменили саму задачу или город. Это может запутать уже откликнувшихся. Создать новую смену вместо изменения текущей?',()=>{v4EditingShiftId=null;createNewShiftFromForm({title,city,time,pay,needed,address,requirements:req,desc})})}else applyUpdate();return}createNewShiftFromForm({title,city,time,pay,needed,address,requirements:req,desc})}
function createNewShiftFromForm(data){let id='s'+Date.now();state.createdShifts.unshift({id,...data,offset:1,filled:0,status:'recruiting'});state.currentShift=id;saveState();toast('Смена опубликована');openPastWorkersModal(id)}
function renderManageShift(){let s=getCurrentShift();if(!s){$('manageBody').innerHTML='<div class="emptyStateCard"><h3>Смена не найдена</h3><button class="btn primary section" onclick="openCreateShift()">Создать смену</button></div>';return}let pct=Math.min(100,Math.round((s.filled||0)/(s.needed||1)*100));$('manageTitle').textContent=s.title;$('manageSub').textContent=s.city+' · '+dateLabel(s.offset)+' · '+s.time;$('manageBody').innerHTML=`<div class="card activeShiftCard"><div class="progressline"><b>${s.filled||0} из ${s.needed}</b><span class="muted">${(s.filled||0)>=s.needed?'Команда собрана':'Команда набирается'}</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="row section"><button class="btn secondary" onclick="openCreateShift('${s.id}')">Изменить условия</button><button class="btn outline" onclick="recruitMore('${s.id}')">Добрать людей</button><button class="btn secondary" onclick="openPastWorkersModal('${s.id}')">Оповестить прошлых исполнителей</button></div>${(s.filled||0)>=s.needed?`<button class="btn primary full section" onclick="confirmStartShift('${s.id}')">Начать смену</button>`:`<div class="help section">Кнопка «Начать смену» появится, когда команда будет собрана.</div>`}<button class="btn danger full section" onclick="deleteShift('${s.id}')">Удалить смену</button></div>`}
function changeShiftPeople(id){openCreateShift(id)}
function deleteShift(id){let s=state.createdShifts.find(x=>x.id===id);if(!s)return;let newApps=Object.values(state.candidateStatus||{}).filter(x=>x==='new').length;openConfirm('Удалить смену?',newApps?`По этой смене есть отклики (${newApps}). Исполнители увидят, что смена отменена.`:'Смена будет удалена из активных.',()=>{s.status='deleted';if(state.currentShift===id)state.currentShift=null;saveState();toast('Смена удалена');go('contractorShifts')})}
function openPastWorkersModal(shiftId){state.currentShift=shiftId||state.currentShift;saveState();let ids=state.pastWorkers||[];let el=$('pastWorkerChoices');if(!ids.length){el.innerHTML='<div class="empty"><b>Прошлых исполнителей пока нет</b><div>После первых завершённых смен здесь появятся люди, с которыми вы уже работали.</div></div>'}else{el.innerHTML=ids.map(id=>{let c=candidates.find(x=>x.id===id);if(!c)return'';return `<div class="pastChoice"><div><b>${c.name}</b><div class="muted tiny">★ ${c.rating} · ${c.shifts} смен</div></div><button class="chip" data-worker="${id}" onclick="this.classList.toggle('active')">Выбрать</button></div>`}).join('')}openModal('pastWorkersModal')}
function selectAllPastWorkers(){document.querySelectorAll('#pastWorkerChoices [data-worker]').forEach(x=>x.classList.add('active'))}
function sendPastWorkerNotice(){let ids=[...document.querySelectorAll('#pastWorkerChoices [data-worker].active')].map(x=>x.dataset.worker);if(!ids.length){toast('Выберите хотя бы одного исполнителя');return}closeModal('pastWorkersModal');toast(`Оповещено: ${ids.length}. «Подрядчик, с которым вы работали, открыл новую смену»`);go('contractorShifts')}
function renderApplicants(){let ids=Object.keys(state.candidateStatus||{});if(!ids.length){$('applicantList').innerHTML='<div class="emptyStateCard"><div class="icon">◌</div><h3>Новых откликов пока нет</h3><p>Когда исполнители откликнутся на вашу смену, они появятся здесь.</p></div>';return}$('applicantList').innerHTML=ids.map(id=>{let c=candidates.find(x=>x.id===id);if(!c)return'';let st=state.candidateStatus[id];return `<div class="person">${avatarHTML(c.name,'')}<div class="grow"><h4>${c.name} ${st==='accepted'?'<span class="badge ok">принят</span>':st==='rejected'?'<span class="badge rejected">отклонён</span>':''}</h4><small><span class="metricStar">★</span> ${c.rating} · ${c.shifts} смен · ${c.skills.join(' · ')}</small><div class="minirow">${st==='new'?`<button class="mini ok" onclick="selectCandidate('${c.id}');confirmApplicant('accept')">Принять</button><button class="mini no" onclick="selectCandidate('${c.id}');confirmApplicant('reject')">Отклонить</button>`:''}<button class="mini" onclick="openCandidateChat('${c.id}')">💬 Чат</button></div></div></div>`}).join('')}
function renderContractorGroupChat(){let msgs=state.contractorGroupMessages||[];$('contractorGroupMessages').innerHTML=msgs.length?msgs.map(m=>`<div class="msg ${m.who===state.contractorProfile.name?'me':''}"><div class="who ${m.role||''}">${m.who}${m.role==='contractor'?' · подрядчик':m.role==='admin'?' · старший':''}</div>${m.text}</div>`).join(''):'<div class="empty"><div class="icon">ϟ</div><b>SPEED HELPER</b><div>Это общий чат конкретной смены. Сообщения команды появятся здесь.</div></div>'}
function renderContractorProfile(){let p=state.contractorProfile,pct=contractorCompletion(p),verified=pct>=80,display=p.company||p.name||'Подрядчик';$('contractorProfileBody').innerHTML=`<div class="card"><div class="profiletop">${avatarHTML(display,p.avatar,true)}<div><h2 class="noMargin">${display}</h2>${verified?'<div class="verify">✓ Надёжный подрядчик</div>':''}<div class="muted tiny">${p.city||''} · <span class="metricStar">★</span> 4.9</div></div></div>${p.bio?`<div class="profileCopy section">${p.bio}</div>`:''}<div class="completeBar"><div class="progressline"><b>Профиль ${pct}%</b><span class="muted">${pct>=100?'Заполнен полностью':'Фото и контакт'}</span></div><div class="progress"><i style="width:${pct}%"></i></div></div>${pct<100?'<div class="notice section"><b>✓ Усильте профиль</b><p>Фото и контакт повышают доверие исполнителей. Компания и описание — необязательны.</p></div>':''}</div><div class="grid2 section"><div class="choice metric"><b>0%</b><small>выплат вовремя</small></div><div class="choice metric"><b><span class="metricStar">★</span> 0.0</b><small>оценка исполнителей</small></div><div class="choice metric"><b>0</b><small>закрытых смен</small></div><div class="choice metric"><b>—</b><small>средний ответ</small></div></div><div class="row section"><button class="btn secondary" onclick="go('contractorFavorites')">Избранные исполнители</button><button class="btn secondary" onclick="go('settings')">Настройки</button></div>`}
function showFallbackSimilar(){let base=jobs[0];deckIds=jobs.filter(j=>j.id!==base.id).slice(0,5).map(j=>j.id);deckIndex=0;deckMode='similar';lastAction=null;renderDeck()}
function refreshDeck(){deckIds=filterJobs();deckIndex=0;lastAction=null;deckMode='all';renderDeck();toast(deckIds.length?'Поиск обновлён':'Новых смен пока нет')}

function init(){const tg=window.Telegram&&window.Telegram.WebApp;if(tg){try{tg.ready();tg.expand()}catch(e){}}setContext();if(state.registered&&state.role){currentScreen=state.role==='worker'?'workerHome':'contractorHome';document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(currentScreen).classList.add('active');buildNav();onScreen(currentScreen)}else{currentScreen='landing';buildNav()}$('csDate').value=new Date(Date.now()+86400000).toISOString().slice(0,10)}
init();
